/**
 * Shape of content/markets.json, generated by scripts/build-content.py from
 * the baseline reports, the sales workbook and the customer studies. Every
 * figure on screen comes from here and carries its source.
 */
export type MarketCode = "CN" | "US" | "EU";

export type DomainKey =
  | "exterior_design"
  | "interior_comfort"
  | "space_practicality"
  | "infotainment_digital"
  | "driver_assistance"
  | "powertrain_range_charging"
  | "driving_dynamics"
  | "quality_nvh"
  | "offering_variants"
  | "general";

export interface Domain {
  key: DomainKey;
  name: string;
  description: string;
}

export interface Sales {
  year: number;
  units: number;
  source: string;
}

export interface WeakestDomain {
  key: DomainKey;
  name: string;
  complaintShare: number;
  rows: number;
}

export interface DomainFigures {
  key: DomainKey;
  name: string;
  rows: number;
  complaints: number;
  likes: number;
  complaintShare: number;
}

export interface ComplaintTheme {
  theme: string;
  domain: DomainKey;
  rows: number;
  complaints: number;
  defects: number;
  difficultToUse: number;
  wants: number;
}

export interface StudyAttribute {
  attribute: string;
  score: number;
}

export interface VehicleStudy {
  sheet: string;
  overall: number | null;
  weakest: StudyAttribute[];
  scale: string;
}

export interface VehicleContent {
  code: string;
  name: string;
  series: string;
  /** Which drawing to show; G68 borrows the G60 body. */
  drawing: "F70" | "G60" | "G70";
  sales: Sales;
  verbatims: number;
  weakestDomain: WeakestDomain | null;
  domains: DomainFigures[];
  complaintThemes: ComplaintTheme[];
  study: VehicleStudy | null;
}

export interface MarketStudy {
  attribute: string;
  score: number;
  overall: number;
  scale: string;
  vehicles: string[];
}

export interface MarketContent {
  code: MarketCode;
  name: string;
  sales: Sales;
  verbatims: { count: number; source: string };
  weakestDomain: WeakestDomain | null;
  weakestDomainSource: string;
  study: MarketStudy | null;
  vehicles: VehicleContent[];
}

export interface MarketsContent {
  generatedAt: string;
  dataVintage: Record<string, string | string[]>;
  domains: Domain[];
  markets: MarketContent[];
}
